// The FrameOS scene store, on the frame. Pick a shelf or search, page through
// the scenes, and Preview or Install one; a scene the frame holds can be
// opened, updated or deleted. The store is asked through the frame's host
// (frameos.store() and frameos.storeAction(), docs/scene-store.md), which does
// the network off the render, so a tap answers at once and the page fills in
// a moment later. Where there is no host (the browser preview) it browses
// straight from the store and installs nothing.
//
// Where you are (the shelf, the search, the page, the scene open) is the
// private `spot` field, kept on disk: preview a scene, come back to the store,
// and it opens on the same spot, drawn from what it showed before any answer
// comes back. Pages already seen are kept with frameos.remember, and covers
// as kept pictures, so going back and forth costs nothing.

const DEFAULT_STORE = 'https://cloud.frameos.net'
const FRESH_MS = 5 * 60 * 1000
const RETRY_MS = 30 * 1000
const PAGES_KEPT = 16

let zoom = 1
const px = (n) => `${Math.round(n * zoom)}px`

// While this interpreter lives: the covers it holds and what it is waiting for.
const covers = new Map() // url -> kept image ref
const failedCovers = new Set()
let coverOrder = []
let pending = '' // the listing asked of the host
let failedKey = ''
let failedAt = 0
let lastPageKey = ''
let query = null // the search field's text while it is edited
let searchOpen = false
let confirmDelete = ''

const WORDS = {
  offline: 'The frame is offline.',
  store_unavailable: 'The store did not answer. Try again in a moment.',
  plane_update_required: 'Installing from the frame needs a newer version of its control plane.',
  rate_limited: 'Too many requests. Wait a minute and try again.',
  too_many_scenes: 'This frame holds as many scenes as it can. Delete one first.',
  panel_locked: 'Changes from the frame are turned off by its owner.',
  frame_update_required: 'This scene needs a newer FrameOS on the frame.',
  frame_not_active: 'The frame is not active on its control plane.',
  scene_requires_compilation: 'This scene cannot be installed from the frame.',
  scene_not_allowed: 'This scene cannot be installed from the frame.',
  invalid_scene: 'The store no longer offers this scene.',
  scene_not_assigned: 'This scene is not on the frame any more.',
  already_assigned: 'This scene is on the frame already.',
  last_scene: 'A frame keeps at least one scene.',
  no_room: 'Not enough memory on the frame for that.',
  scenes_payload_too_large: 'This scene is too large for the frame.',
}
const BUSY = {
  browse: 'Loading',
  install: 'Installing',
  preview: 'Opening the preview',
  update: 'Updating',
  remove: 'Deleting',
  discard: 'Discarding the preview',
}

function readSpot(app) {
  let spot = app.state.spot
  if (typeof spot === 'string') {
    try {
      spot = JSON.parse(spot)
    } catch (e) {
      spot = null
    }
  }
  return spot && typeof spot === 'object' ? spot : {}
}

const saveSpot = (spot) => frameos.setState('spot', spot)

// encodeURIComponent leaves !'()* alone, and the host takes a query string of
// letters, digits and -_.~%&=+, only.
const encode = (text) =>
  encodeURIComponent(text).replace(/[!'()*]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase())

const keyOf = (params) => String(params || '').replace(/&?categories=1/, '')

function paramsFor(spot, limit, look, needShelves) {
  const parts = []
  if (spot.q) parts.push('q=' + encode(spot.q))
  if (spot.shelf) parts.push('category=' + encode(spot.shelf))
  // A panel that animates gets the scenes that move first; e-paper, which
  // cannot show them, is not offered them at all.
  else if (!spot.q && look.fast) parts.push('prefer=realtime')
  if (look.paper && spot.shelf !== 'realtime') parts.push('exclude=realtime')
  parts.push('page=' + (spot.page || 1), 'limit=' + limit)
  if (needShelves) parts.push('categories=1')
  return parts.join('&')
}

function remembered() {
  const pages = frameos.recall('pages')
  return pages && typeof pages === 'object' ? pages : {}
}

function keep(pages, key, answer) {
  pages[key] = { at: Date.now(), more: !!answer.more, scenes: (answer.scenes || []).slice(0, 48) }
  const keys = Object.keys(pages)
  if (keys.length > PAGES_KEPT) {
    keys.sort((a, b) => pages[a].at - pages[b].at)
    for (const old of keys.slice(0, keys.length - PAGES_KEPT)) delete pages[old]
  }
  frameos.remember('pages', pages)
}

// The listing for `params`: what is kept, what the host just brought, or a
// fetch of our own. Asks again (in the background) when it is old.
function listing(spot, params, facts, base, sync) {
  const key = keyOf(params)
  const pages = remembered()
  if (facts && facts.listing && !facts.busy) {
    const brought = keyOf(facts.params)
    if (brought === pending || !pages[brought]) {
      keep(pages, brought, facts.listing)
      if (facts.listing.categories) spot.shelves = facts.listing.categories
      if (brought === pending) pending = ''
    }
  }
  if (facts && !facts.busy && pending && facts.error) {
    failedKey = pending
    failedAt = Date.now()
    pending = ''
  }
  const page = pages[key]
  const stale = !page || Date.now() - page.at > FRESH_MS
  const failedRecently = failedKey === key && Date.now() - failedAt < RETRY_MS
  let error = failedRecently && !page ? (facts && facts.error) || 'store_unavailable' : ''
  if (stale && !failedRecently) {
    if (sync) {
      let code = 'store_unavailable'
      try {
        const version = facts ? '&version=' + encode(facts.version) : ''
        const response = frameos.httpRequest(`${base}/api/store/device/scenes?${params}${version}`, { timeoutMs: 15000 })
        if (response.status === 429) code = 'rate_limited'
        const answer = response.status === 200 && response.body ? JSON.parse(response.body) : null
        if (answer && Array.isArray(answer.scenes)) {
          keep(pages, key, answer)
          if (answer.categories) spot.shelves = answer.categories
          return { page: pages[key], loading: false, error: '' }
        }
      } catch (e) {
        // the words below
      }
      failedKey = key
      failedAt = Date.now()
      error = code
    } else if (!facts.busy) {
      frameos.storeAction('browse', { params })
      pending = key
    }
  }
  return { page, loading: stale && !error && !page, error }
}

function coverUrl(base, image) {
  return image ? (image.startsWith('/') ? base + image : image) : ''
}

// A store cover is the publisher's picture, often a megabyte of PNG: 6 s a
// card on an ESP32. The store also lists `thumb`, a JPEG of at most
// THUMB_WIDTH on its CDN, which is all a card needs (and a scene's page on a
// small screen).
const THUMB_WIDTH = 512
const coverFor = (base, scene, width) =>
  coverUrl(base, scene.thumb && width <= THUMB_WIDTH * 1.25 ? scene.thumb : scene.image)

// A cover, kept under `key`: its url, or the url and "#big" for the scene
// page's larger copy.
function loadCover(key, width, height, limit) {
  const url = key.endsWith('#big') ? key.slice(0, -4) : key
  const result = frameos.fetchImage(url, { keep: true, width, height, fit: 'cover' })
  if (!result || !result.image) {
    failedCovers.add(key)
    return
  }
  covers.set(key, result.image)
  coverOrder = coverOrder.filter((u) => u !== key).concat(key)
  while (coverOrder.length > limit) {
    const old = coverOrder.shift()
    frameos.releaseImage(covers.get(old))
    covers.delete(old)
  }
}

// What the frame is: how it draws, and how much room it has.
function lookOf(app) {
  const paper = app.frame.paper === true
  const mono = app.frame.color === false
  const width = (app.frame.rotate || 0) % 180 !== 0 ? app.frame.height : app.frame.width
  const height = (app.frame.rotate || 0) % 180 !== 0 ? app.frame.width : app.frame.height
  const shortSide = Math.min(width, height) * (app.frame.scale || 1)
  zoom = Math.max(0.75, Math.min(2.25, Math.round((shortSide / 480) * 4) / 4))
  const ink = paper || mono
  return {
    paper,
    fast: !paper,
    width,
    height,
    wide: width >= 600 * zoom,
    embedded: app.frame.embedded === true,
    scale: app.frame.scale || 1,
    bg: ink ? 'bg-white' : 'bg-[#0b0e14]',
    panel: ink ? 'bg-white' : 'bg-[#121722]',
    card: ink ? 'bg-white' : 'bg-[#1a2030]',
    text: ink ? 'text-black' : 'text-white',
    muted: ink ? 'text-black' : 'text-[#8b93a7]',
    line: ink ? 'border-black' : 'border-[#232a3a]',
    accent: ink ? 'bg-black text-white' : 'bg-[#3b82f6] text-white',
    accentText: ink ? 'text-black underline' : 'text-[#60a5fa]',
    soft: ink ? 'bg-white border-2 border-black text-black' : 'bg-[#232a3a] text-white',
    press: paper ? '' : ink ? 'active:bg-black active:text-white' : 'active:bg-[#2c3550]',
    placeholder: ink ? 'bg-white' : 'bg-[#232a3a]',
    cardColor: ink ? '#ffffff' : '#1a2030',
    pageColor: ink ? '#ffffff' : '#0b0e14',
  }
}

// Rounded corners for a picture: the box clips square, so the corners are
// painted over in the color around it, each its own corner-sized drawing. One
// drawing the picture's size (the box minus a rounded box) cost a mask over
// the whole picture on every repaint: half a second a pass on an ESP32.
const corner = (r, color, d, where) => (
  <svg className={`absolute ${where}`} width={r} height={r} viewBox={`0 0 ${r} ${r}`}>
    <path fill={color} d={d} />
  </svg>
)
const Corners = ({ radius, color }) => {
  const r = Math.round(radius * zoom)
  return [
    corner(r, color, `M0 0H${r}A${r} ${r} 0 0 0 0 ${r}Z`, 'top-0 left-0'),
    corner(r, color, `M${r} 0V${r}A${r} ${r} 0 0 0 0 0Z`, 'top-0 right-0'),
    corner(r, color, `M${r} ${r}H0A${r} ${r} 0 0 0 ${r} 0Z`, 'bottom-0 right-0'),
    corner(r, color, `M0 ${r}V0A${r} ${r} 0 0 0 ${r} ${r}Z`, 'bottom-0 left-0'),
  ]
}

const Bag = ({ size, className = '' }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}] ${className}`}>
    <path fill="currentColor" d="M6 7V6a6 6 0 0 1 12 0v1h2.5l-1 15h-15l-1-15ZM8 7h8V6a4 4 0 0 0-8 0Z" />
  </svg>
)

const SearchGlyph = ({ size }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" d="M10.5 17a6.5 6.5 0 1 1 0-13a6.5 6.5 0 0 1 0 13ZM15.5 15.5L21 21" />
  </svg>
)

const Chevron = ({ size, left }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round" d={left ? 'M15 5L8 12L15 19' : 'M9 5L16 12L9 19'} />
  </svg>
)

const Check = ({ size }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" d="M5 12.5L10 17.5L19 7" />
  </svg>
)

// What the frame holds of a store scene: installed (and how old), previewed.
function standing(scene, facts) {
  if (!facts) return {}
  const mine = (facts.installed || []).find((row) => row.store === scene.id)
  const preview = facts.preview && facts.preview.store === scene.id ? facts.preview : null
  return { mine, preview, newer: !!mine && mine.v < scene.version }
}

function Badge({ look, children, strong }) {
  return (
    <div className={`flex items-center gap-[${px(3)}] px-[${px(7)}] h-[${px(20)}] rounded-full text-[${px(11)}] font-bold ${strong ? look.accent : look.soft}`}>
      {children}
    </div>
  )
}

function Cover({ look, url, width, height, name, radius, around }) {
  const ref = url ? covers.get(url) : null
  return (
    <div className={`relative w-[${px(width)}] h-[${px(height)}] shrink-0`}>
      {ref ? (
        <img className={`w-[${px(width)}] h-[${px(height)}] object-cover`} src={ref} />
      ) : (
        <div className={`flex items-center justify-center w-[${px(width)}] h-[${px(height)}] rounded-[${px(radius)}] ${look.placeholder} ${look.muted}`}>
          <span className={`text-[${px(Math.round(height / 2.6))}] font-bold`}>{(name || '?').trim().charAt(0).toUpperCase()}</span>
        </div>
      )}
      {ref ? <Corners radius={radius} color={around} /> : null}
    </div>
  )
}

function Card({ look, scene, base, facts, width, onOpen }) {
  const coverHeight = Math.round((width * 3) / 4)
  const { mine, preview, newer } = standing(scene, facts)
  return (
    <div className={`flex flex-col w-[${px(width)}] rounded-[${px(12)}] ${look.card} ${look.press}`} onClick={onOpen}>
      <Cover look={look} url={coverFor(base, scene, Math.round(width * zoom * look.scale))} width={width} height={coverHeight} name={scene.name} radius={12} around={look.pageColor} />
      <div className={`flex flex-col gap-[${px(2)}] h-[${px(52)}] px-[${px(10)}] py-[${px(6)}]`}>
        <span className={`text-[${px(14)}] font-bold truncate`}>{scene.name}</span>
        <div className={`flex items-center gap-[${px(6)}] h-[${px(18)}]`}>
          <span className={`flex-1 min-w-0 text-[${px(12)}] truncate ${look.muted}`}>{scene.by || 'FrameOS'}</span>
          {preview ? (
            <Badge look={look} strong>Preview</Badge>
          ) : newer ? (
            <Badge look={look} strong>Update</Badge>
          ) : mine ? (
            <Badge look={look}>
              <Check size={11} />
              On frame
            </Badge>
          ) : null}
        </div>
      </div>
    </div>
  )
}

function Button({ look, strong, onClick, children, disabled }) {
  const tone = disabled ? `${look.soft} opacity-50` : strong ? look.accent : look.soft
  return (
    <div
      className={`flex items-center justify-center gap-[${px(6)}] h-[${px(44)}] px-[${px(18)}] rounded-[${px(10)}] text-[${px(15)}] font-bold ${tone} ${disabled ? '' : look.press}`}
      onClick={disabled ? undefined : onClick}
    >
      {children}
    </div>
  )
}

function shelfTitle(spot) {
  if (spot.q) return `Results for "${spot.q}"`
  if (!spot.shelf) return 'Featured'
  const shelf = (spot.shelves || []).find((s) => s.slug === spot.shelf)
  return shelf ? shelf.title : spot.shelf
}

// The shelves, as this frame wants them: the scenes that move first on a panel
// that shows them, and not at all on e-paper.
function shelvesFor(spot, look) {
  const all = spot.shelves || []
  const moving = all.filter((s) => s.slug === 'realtime')
  const rest = all.filter((s) => s.slug !== 'realtime')
  return [{ slug: '', title: 'Featured' }, ...(look.paper ? [] : moving), ...rest]
}

// What the host says of the action this store asked for `scene` (any scene
// while it runs): the words for it, or "".
function statusLine(facts, spot, scene) {
  if (!facts) return ''
  if (facts.busy && facts.busy !== 'browse') return `${BUSY[facts.busy] || 'Working'}…`
  if (!scene || !spot.asked || spot.asked.store !== scene.id) return ''
  if (facts.error) return WORDS[facts.error] || `That did not work (${facts.error}).`
  if (facts.done === 'uptodate') return 'It is the newest version already.'
  if (facts.done === 'install') return 'Installed. It is in the scene list now.'
  if (facts.done === 'update') return 'Updated to the newest version.'
  if (facts.done === 'remove') return 'Deleted from the frame.'
  if (facts.done === 'discard') return 'The preview is gone.'
  return ''
}

// The scene page's picture, in layout pixels. Decoded at exactly the size it
// is drawn, so drawing it is a copy: one decoded at the panel's width and
// drawn 40 px narrower was resampled on every repaint (0.44 s on an ESP32).
function bigCoverWidth(look) {
  return look.wide
    ? Math.min(Math.round(((look.width / zoom) * 0.46) / 4) * 4, Math.round((((look.height / zoom) - 120) * 4) / 3))
    : Math.min(Math.round((look.width / zoom) - 40), Math.round((((look.height / zoom) * 0.42) * 4) / 3))
}

function Detail({ look, app, spot, facts, base, hasHost }) {
  const scene = spot.detail
  const { mine, preview, newer } = standing(scene, facts)
  const isLayout = scene.category === 'layouts'
  const busy = !!(facts && facts.busy && facts.busy !== 'browse')
  const leave = () => {
    spot.detail = null
    confirmDelete = ''
    saveSpot(spot)
  }
  const ask = (action, extra) => {
    spot.asked = { action, store: scene.id }
    saveSpot(spot)
    frameos.storeAction(action, { store: scene.id, name: scene.name, ...extra })
  }
  const big = bigCoverWidth(look)
  const bigHeight = Math.round((big * 3) / 4)
  // The card's copy (the thumbnail when there is one) until the larger one
  // is in, which is the thumbnail again where it is big enough.
  const url = coverFor(base, scene, 0)
  const bigUrl = coverFor(base, scene, Math.round(big * zoom * look.scale))
  const sharp = bigUrl ? bigUrl + '#big' : ''
  const buttons = []
  if (!hasHost) {
    buttons.push(
      <span className={`text-[${px(14)}] ${look.muted}`}>Previews and installs happen on the frame itself.</span>
    )
  } else if (preview) {
    buttons.push(
      <Button look={look} strong disabled={busy} onClick={() => ask('install', { show: true })}>Install</Button>,
      <Button look={look} disabled={busy} onClick={() => frameos.dispatch('setCurrentScene', { sceneId: preview.id })}>Show</Button>,
      <Button look={look} disabled={busy} onClick={() => ask('discard')}>Discard</Button>
    )
  } else if (mine) {
    if (!isLayout) {
      buttons.push(
        <Button look={look} strong={!newer} disabled={busy} onClick={() => frameos.dispatch('setCurrentScene', { sceneId: mine.id })}>Open</Button>
      )
    }
    if (newer) buttons.push(<Button look={look} strong disabled={busy} onClick={() => ask('update')}>Update</Button>)
    buttons.push(
      confirmDelete === scene.id ? (
        <Button look={look} disabled={busy} onClick={() => { confirmDelete = ''; ask('remove') }}>Tap again to delete</Button>
      ) : (
        <Button look={look} disabled={busy} onClick={() => { confirmDelete = scene.id }}>Delete</Button>
      )
    )
  } else {
    if (!isLayout) {
      buttons.push(<Button look={look} disabled={busy} onClick={() => ask('preview')}>Preview</Button>)
    }
    buttons.push(<Button look={look} strong disabled={busy} onClick={() => ask('install', { show: false })}>Install</Button>)
  }
  const status = statusLine(facts, spot, scene)
  const info = (
    <div className={`flex flex-col gap-[${px(10)}] flex-1 min-w-0`}>
      <span className={`text-[${px(26)}] font-bold leading-tight line-clamp-2`}>{scene.name}</span>
      <span className={`text-[${px(14)}] ${look.muted} truncate`}>
        {[scene.by || 'FrameOS', titleOfShelf(spot, scene.category), `version ${scene.version}`].filter(Boolean).join(' · ')}
      </span>
      {scene.about ? <span className={`text-[${px(15)}] leading-snug line-clamp-5`}>{scene.about}</span> : null}
      {isLayout ? (
        <span className={`text-[${px(13)}] ${look.muted}`}>A layout goes around every scene: once it is installed, pick it under Layout in the frame's settings.</span>
      ) : null}
      {mine && newer ? <span className={`text-[${px(13)}] ${look.muted}`}>{`The frame has version ${mine.v}.`}</span> : null}
      <div className={`flex flex-wrap items-center gap-[${px(8)}] pt-[${px(4)}]`}>{buttons}</div>
      {status ? <span className={`text-[${px(14)}] ${look.accentText}`}>{status}</span> : null}
    </div>
  )
  const picture = (
    <Cover look={look} url={covers.has(sharp) ? sharp : url} width={big} height={bigHeight} name={scene.name} radius={14} around={look.pageColor} />
  )
  return (
    <div className={`flex flex-col w-full h-full ${look.bg} ${look.text}`}>
      <div className={`flex items-center h-[${px(52)}] px-[${px(8)}] shrink-0`}>
        <div className={`flex items-center gap-[${px(2)}] h-[${px(40)}] pl-[${px(4)}] pr-[${px(12)}] rounded-[${px(10)}] ${look.accentText} ${look.press}`} onClick={leave}>
          <Chevron size={22} left />
          <span className={`text-[${px(16)}] font-bold`}>{spot.q ? 'Results' : shelfTitle(spot)}</span>
        </div>
      </div>
      {look.wide ? (
        <div className={`flex flex-1 min-h-0 items-center gap-[${px(22)}] px-[${px(20)}] pb-[${px(36)}]`}>
          {picture}
          {info}
        </div>
      ) : (
        <div className={`flex flex-col flex-1 min-h-0 items-center gap-[${px(14)}] px-[${px(20)}] pb-[${px(16)}] overflow-y-auto`}>
          {picture}
          {info}
        </div>
      )}
    </div>
  )
}

function titleOfShelf(spot, slug) {
  const shelf = (spot.shelves || []).find((s) => s.slug === slug)
  return shelf ? shelf.title : ''
}

export function get(app) {
  const look = lookOf(app)
  const facts = frameos.store()
  const hasHost = !!facts
  const base = String((facts && facts.url) || DEFAULT_STORE).replace(/\/+$/, '')
  // E-paper draws once per answer: a refresh to say "Loading" costs seconds.
  const sync = !hasHost || look.paper
  const spot = readSpot(app)
  spot.page = Math.max(1, spot.page || 1)

  // The grid: as many cards as fit, a page a screen, never so many that a
  // card is too small to read.
  const sideWidth = look.wide ? Math.round(Math.min(220, Math.max(170, look.width / zoom / 4.2))) : 0
  const mainWidth = look.width / zoom - sideWidth
  const gap = 14
  const pad = look.wide ? 20 : 14
  const textHeight = 52
  const headerHeight = look.wide ? 76 : 108
  const footerHeight = 46
  const roomHeight = look.height / zoom - headerHeight - footerHeight
  let cols = 2
  let rows = 1
  let cardWidth = 0
  let best = -1
  for (let r = 1; r <= 5; r++) {
    for (let c = 2; c <= 6; c++) {
      const width = Math.floor(
        Math.min((mainWidth - pad * 2 - gap * (c - 1)) / c, (((roomHeight - gap * (r - 1)) / r - textHeight) * 4) / 3)
      )
      const score = width >= 130 && width <= 280 ? r * c * Math.pow(width, 1.2) : -1
      if (score > best) {
        best = score
        cols = c
        rows = r
        cardWidth = width
      }
    }
  }
  if (best < 0) cardWidth = Math.floor((mainWidth - pad * 2 - gap) / 2)
  const cardHeight = Math.round((cardWidth * 3) / 4) + textHeight
  const limit = Math.min(24, cols * rows)

  const params = paramsFor(spot, limit, look, !spot.shelves)
  const { page, loading, error } = listing(spot, params, facts, base, sync)
  const scenes = page ? page.scenes.slice(0, limit) : []
  const more = page ? page.more : false
  // What reopening draws before any answer: this page as it was.
  saveSpot(spot)

  // Covers: none on the pass that shows a page (it paints at once), then one
  // a pass until the page has them all. E-paper takes them all before its
  // one refresh.
  const decode = (w, h) => [Math.round(w * zoom * look.scale), Math.round(h * zoom * look.scale)]
  const [coverW, coverH] = decode(cardWidth, Math.round((cardWidth * 3) / 4))
  const keepLimit = look.embedded ? 18 : 40
  const [bigW, bigH] = decode(bigCoverWidth(look), Math.round((bigCoverWidth(look) * 3) / 4))
  const wanted = spot.detail
    ? [coverFor(base, spot.detail, bigW) + '#big']
    : scenes.map((scene) => coverFor(base, scene, coverW))
  const missing = wanted.filter((url) => url && url !== '#big' && !covers.has(url) && !failedCovers.has(url))
  const pageKey = spot.detail ? 'detail:' + spot.detail.id : keyOf(params)
  const load = (key) =>
    key.endsWith('#big')
      ? loadCover(key, bigW, bigH, keepLimit)
      : loadCover(key, coverW, coverH, keepLimit)
  if (missing.length > 0) {
    if (look.paper) missing.forEach(load)
    else if (pageKey === lastPageKey) load(missing[0])
  }
  lastPageKey = pageKey
  const stillMissing = wanted.filter((url) => url && url !== '#big' && !covers.has(url) && !failedCovers.has(url))
  if (stillMissing.length > 0 && !look.paper) frameos.setNextSleep(0.05)

  // The next page, asked for while nothing else runs, so a swipe answers at
  // once (not on e-paper: every answer there is a refresh).
  if (hasHost && !look.paper && !loading && more && !facts.busy && stillMissing.length === 0 && !spot.detail) {
    const next = paramsFor({ ...spot, page: spot.page + 1 }, limit, look, false)
    if (!remembered()[keyOf(next)]) {
      frameos.storeAction('browse', { params: next })
      pending = keyOf(next)
    }
  }

  if (spot.detail) {
    return <Detail look={look} app={app} spot={spot} facts={facts} base={base} hasHost={hasHost} />
  }

  const go = (change) => {
    Object.assign(spot, change)
    confirmDelete = ''
    saveSpot(spot)
  }
  const turn = (by) => {
    if (by > 0 && !more) return
    if (by < 0 && spot.page <= 1) return
    go({ page: spot.page + by })
  }
  const search = () => {
    const text = String(query == null ? spot.q || '' : query).trim()
    query = null
    searchOpen = false
    go({ q: text, shelf: '', page: 1 })
  }
  const shelves = shelvesFor(spot, look)
  const status = statusLine(facts, spot, null)
  const busyBrowse = loading || (facts && facts.busy === 'browse' && pending === keyOf(params))

  const searchField = (
    <div className={`flex items-center gap-[${px(8)}] h-[${px(40)}] px-[${px(12)}] rounded-[${px(10)}] ${look.soft} ${look.wide ? `w-[${px(240)}]` : 'flex-1'}`}>
      <SearchGlyph size={18} />
      <input
        className={`flex-1 min-w-0 h-[${px(40)}] text-[${px(15)}] bg-transparent`}
        value={query == null ? spot.q || '' : query}
        placeholder="Search the store"
        onChange={(e) => {
          query = e.target.value
        }}
        onKeyDown={(e) => {
          if (e.key === 'Enter') search()
        }}
      />
      {spot.q ? (
        <div className={`text-[${px(13)}] font-bold ${look.accentText}`} onClick={() => { query = null; go({ q: '', page: 1 }) }}>Clear</div>
      ) : null}
    </div>
  )

  const grid = []
  const shown = loading ? Array.from({ length: limit }, (_, i) => ({ id: 'loading' + i, name: '', loading: true })) : scenes
  for (let r = 0; r < rows; r++) {
    const row = shown.slice(r * cols, r * cols + cols)
    if (row.length === 0) break
    grid.push(
      <div className={`flex gap-[${px(gap)}]`}>
        {row.map((scene) =>
          scene.loading ? (
            <div className={`w-[${px(cardWidth)}] h-[${px(cardHeight)}] rounded-[${px(12)}] ${look.placeholder}`} />
          ) : (
            <Card look={look} scene={scene} base={base} facts={facts} width={cardWidth} onOpen={() => go({ detail: scene })} />
          )
        )}
      </div>
    )
  }

  const empty = !loading && scenes.length === 0
  const gridWidth = cols * cardWidth + (cols - 1) * gap
  const body = (
    <div
      className={`flex flex-col flex-1 min-h-0 items-center px-[${px(pad)}]`}
      onSwipe={(e) => {
        if (e.direction === 'left') turn(1)
        else if (e.direction === 'right') turn(-1)
      }}
    >
      {error && scenes.length === 0 ? (
        <div className={`flex flex-col items-center justify-center flex-1 self-stretch gap-[${px(12)}] ${look.muted}`}>
          <span className={`text-[${px(16)}] text-center`}>{WORDS[error] || 'The store did not answer.'}</span>
          <Button look={look} onClick={() => { failedKey = ''; go({}) }}>Try again</Button>
        </div>
      ) : empty ? (
        <div className={`flex items-center justify-center flex-1 self-stretch text-[${px(16)}] ${look.muted}`}>{spot.q ? 'No scenes match that.' : 'Nothing on this shelf yet.'}</div>
      ) : (
        <div className={`flex flex-col gap-[${px(gap)}] w-[${px(gridWidth)}]`}>{grid}</div>
      )}
    </div>
  )

  const pager = (
    <div className={`flex items-center justify-between h-[${px(footerHeight)}] px-[${px(pad)}] shrink-0`}>
      <span className={`flex-1 min-w-0 text-[${px(13)}] truncate ${look.accentText}`}>{status || (busyBrowse ? 'Loading…' : '')}</span>
      <div className={`flex items-center gap-[${px(6)}]`}>
        <div className={`flex items-center justify-center w-[${px(40)}] h-[${px(34)}] rounded-[${px(8)}] ${spot.page > 1 ? `${look.soft} ${look.press}` : `${look.muted} opacity-40`}`} onClick={() => turn(-1)}>
          <Chevron size={18} left />
        </div>
        <span className={`w-[${px(64)}] text-center text-[${px(13)}] ${look.muted}`}>{`Page ${spot.page}`}</span>
        <div className={`flex items-center justify-center w-[${px(40)}] h-[${px(34)}] rounded-[${px(8)}] ${more ? `${look.soft} ${look.press}` : `${look.muted} opacity-40`}`} onClick={() => turn(1)}>
          <Chevron size={18} />
        </div>
      </div>
    </div>
  )

  if (look.wide) {
    return (
      <div className={`flex w-full h-full ${look.bg} ${look.text}`}>
        <div className={`flex flex-col w-[${px(sideWidth)}] h-full ${look.panel} border-r ${look.line} shrink-0`}>
          <div className={`flex items-center gap-[${px(8)}] h-[${px(64)}] px-[${px(16)}] shrink-0`}>
            <div className={`flex items-center justify-center w-[${px(32)}] h-[${px(32)}] rounded-[${px(9)}] ${look.accent}`}>
              <Bag size={18} />
            </div>
            <span className={`text-[${px(18)}] font-bold whitespace-nowrap`}>Scene store</span>
          </div>
          <div className={`flex flex-col flex-1 min-h-0 gap-[${px(2)}] px-[${px(8)}] pb-[${px(8)}] overflow-y-auto`}>
            {shelves.map((shelf) => {
              const on = !spot.q && (spot.shelf || '') === shelf.slug
              return (
                <div
                  className={`flex items-center gap-[${px(8)}] h-[${px(36)}] px-[${px(10)}] rounded-[${px(8)}] shrink-0 ${on ? look.accent : look.press}`}
                  onClick={() => go({ shelf: shelf.slug, q: '', page: 1 })}
                >
                  <span className={`flex-1 min-w-0 text-[${px(14)}] truncate ${on ? 'font-bold' : ''}`}>{shelf.title}</span>
                  {shelf.slug === 'realtime' ? <div className={`w-[${px(7)}] h-[${px(7)}] rounded-full ${on ? 'bg-white' : 'bg-[#22c55e]'}`} /> : null}
                </div>
              )
            })}
          </div>
        </div>
        <div className={`flex flex-col flex-1 min-w-0 h-full`}>
          <div className={`flex items-center gap-[${px(12)}] h-[${px(headerHeight)}] px-[${px(pad)}] shrink-0`}>
            <span className={`flex-1 min-w-0 text-[${px(24)}] font-bold truncate`}>{shelfTitle(spot)}</span>
            {searchField}
          </div>
          {body}
          {pager}
        </div>
      </div>
    )
  }

  // Narrow: the shelves are a select, search a row of its own.
  return (
    <div className={`flex flex-col w-full h-full ${look.bg} ${look.text}`}>
      <div className={`flex flex-col gap-[${px(8)}] h-[${px(headerHeight)}] px-[${px(pad)}] pt-[${px(10)}] shrink-0`}>
        <div className={`flex items-center gap-[${px(8)}] h-[${px(40)}]`}>
          <div className={`flex items-center justify-center w-[${px(30)}] h-[${px(30)}] rounded-[${px(8)}] ${look.accent} shrink-0`}>
            <Bag size={17} />
          </div>
          <span className={`flex-1 min-w-0 text-[${px(18)}] font-bold truncate`}>Scene store</span>
          <div className={`flex items-center justify-center w-[${px(40)}] h-[${px(40)}] rounded-[${px(10)}] ${searchOpen || spot.q ? look.accent : look.soft} ${look.press}`} onClick={() => { searchOpen = !searchOpen }}>
            <SearchGlyph size={18} />
          </div>
        </div>
        {searchOpen || spot.q ? (
          searchField
        ) : (
          <select
            className={`h-[${px(40)}] px-[${px(12)}] rounded-[${px(10)}] text-[${px(15)}] ${look.soft}`}
            value={spot.shelf || ''}
            onChange={(e) => go({ shelf: e.target.value, q: '', page: 1 })}
          >
            {shelves.map((shelf) => (
              <option value={shelf.slug} className={(spot.shelf || '') === shelf.slug ? `${look.accent} rounded` : `${look.press} rounded`}>
                {shelf.title}
              </option>
            ))}
          </select>
        )}
      </div>
      {body}
      {pager}
    </div>
  )
}
